#include <stdio.h>

static int letter_index(const unsigned char *s, int *bytes) {
    *bytes = 1;

    if (s[0] >= 'a' && s[0] <= 'z') {
        return s[0] - 'a';
    }

    if (s[0] == 0xC3 && s[1] != '\0') {
        *bytes = 2;
        switch (s[1]) {
            case 0xA1: case 0xA0: case 0xA2: case 0xA3: case 0xA4: return 0;  /* a */
            case 0xA9: case 0xAA: return 4;                                  /* e */
            case 0xAD: return 8;                                              /* i */
            case 0xB3: case 0xB4: case 0xB5: return 14;                       /* o */
            case 0xBA: return 20;                                             /* u */
            case 0xA7: return 2;                                              /* c */
            default: return 26;
        }
    }

    return 26;
}

static int count_word(const unsigned char *s, int freq[27], int allow_star) {
    int length = 0;

    for (int i = 0; s[i] != '\0'; ) {
        if (allow_star && s[i] == '*') {
            length++;
            i++;
            continue;
        }

        int bytes;
        int index = letter_index(s + i, &bytes);
        freq[index]++;
        length++;
        i += bytes;
    }

    return length;
}

int main(void) {
    unsigned char p[512], a[512];
    int freq_p[27] = {0}, freq_a[27] = {0};

    if (scanf("%511s %511s", p, a) != 2) {
        return 0;
    }

    int length_p = count_word(p, freq_p, 0);
    int length_a = count_word(a, freq_a, 1);

    int valid = (length_p == length_a);
    for (int i = 0; i < 27; i++) {
        if (freq_a[i] > freq_p[i]) {
            valid = 0;
        }
    }

    printf("%c\n", valid ? 'S' : 'N');
    return 0;
}
```

